// UnitMeter は meter。
const UnitMeter Unit = "meter"

// UnitInch は inch。
const UnitInch Unit = "inch"

// UnitFoot は foot。
const UnitFoot Unit = "foot"

// UnitUnknown は unknown。
const UnitUnknown Unit = "unknown"

// ElementCounts: 種類ごとの要素の数
type ElementCounts struct {
	// 線分
	Lines *int64 `json:"lines,omitempty"`

	// 文字
	Texts *int64 `json:"texts,omitempty"`

	// 円。マイナーバージョン 81 から
	Circles *int64 `json:"circles,omitempty"`

	// 円弧・楕円弧・スプラインなどの曲線。マイナーバージョン 81 から
	Curves *int64 `json:"curves,omitempty"`

	// 折れ線。マイナーバージョン 81 から
	Polylines *int64 `json:"polylines,omitempty"`

	// 書式つきの文字。マイナーバージョン 81 から
	FormattedTexts *int64 `json:"formatted_texts,omitempty"`

	// 寸法。マイナーバージョン 81 から
	Dimensions *int64 `json:"dimensions,omitempty"`

	// 引出線。マイナーバージョン 81 から
	Leaders *int64 `json:"leaders,omitempty"`

	// 引出線つきの注記。マイナーバージョン 81 から
	Callouts *int64 `json:"callouts,omitempty"`

	// 表。マイナーバージョン 81 から
	Tables *int64 `json:"tables,omitempty"`

	// アンダーレイ。マイナーバージョン 81 から
	Underlays *int64 `json:"underlays,omitempty"`

	// 記号の配置。中の要素を展開しない。マイナーバージョン 81 から
	Symbols *int64 `json:"symbols,omitempty"`

	// ハッチング。マイナーバージョン 81 から
	Hatches *int64 `json:"hatches,omitempty"`

	// 点。マイナーバージョン 81 から
	Points *int64 `json:"points,omitempty"`
}

// ViewDetail: 2D のビュー。変換行列と切り抜きを保ち、尺度・向き・見えるモデル範囲を決定的に求める
type ViewDetail struct {
	// 対象の実寸の空間の公開 ID
	Space *string `json:"space,omitempty"`

	// モデル座標から用紙の mm への [a,b,c,d,e,f]。点を (ax+by+c,dx+ey+f) に写す
	Matrix []float64 `json:"matrix,omitempty"`

	// モデルの X 軸・Y 軸の 1 単位に対応する用紙の長さ [SX,SY]（mm）。回転・せん断・反転でも各軸の正の長さを返す
	Scale []float64 `json:"scale,omitempty"`

	// モデル単位を mm に直した、各軸の縮尺の比 [SX,SY]。1:100 なら 0.01。単位不明なら持たない
	Ratio []float64 `json:"ratio,omitempty"`

	// 用紙の X 軸から見たモデルの X 軸の向き。度、反時計回り、-180〜180
	Rotation *float64 `json:"rotation,omitempty"`

	// 変換が向きを反転する
	Mirrored *bool `json:"mirrored,omitempty"`

	// 用紙の mm での切り抜きの頂点。元の順を保ち、空なら切り抜かない
	Clip []Point2 `json:"clip,omitempty"`

	// 同じ頂点を逆変換したモデル座標。元の順を保つ
	ModelClip []Point2 `json:"model_clip,omitempty"`

	// model_clip を囲む範囲。切り抜きが空なら持たない。モデルの単位
	Extent *Extent `json:"extent,omitempty"`

	// ビューの出所
	Source *Source `json:"source,omitempty"`
}

// Extent: 点を囲む、軸に沿った長方形
type Extent struct {
	// X の最小
	MinX *float64 `json:"min_x,omitempty"`

	// Y の最小
	MinY *float64 `json:"min_y,omitempty"`

	// X の最大
	MaxX *float64 `json:"max_x,omitempty"`

	// Y の最大
	MaxY *float64 `json:"max_y,omitempty"`
}

// EntitiesRequest: 開いた文書を図面モデル（L2、決定 0022）に変換し、要素の一覧を返す。実寸の空間、用紙の順に、それぞれの要素を入力の順に並べる（決定 0117）
type EntitiesRequest struct {
	// メッセージのスキーマのメジャーバージョン。今は 1
	V *int64 `json:"v,omitempty"`

	// 予算の単位ごとの上限。書かない単位は既定値にする（決定 0010）
	Budget *Budget `json:"budget,omitempty"`

	// 予算で止まったとき、止まった所までの結果を求める。書かなければ false（決定 0010）
	Partial *bool `json:"partial,omitempty"`

	// 診断ごとに返す場所の数。書かなければ 16（決定 0009）
	MaxPlaces *int64 `json:"max_places,omitempty"`

	// 時間の上限（ミリ秒）。ネイティブの API が時計を見て止める。止まる所は環境で変わる。wasm では受け付けない（決定 0010）
	TimeLimitMs *int64 `json:"time_limit_ms,omitempty"`

	// op の名前
	Op string `json:"op,omitempty"`

	// 文書の名前。open で作ったもの
	Doc *string `json:"doc,omitempty"`

	// すべての条件で絞った後の、返す最初の要素の位置。前の応答の next_offset を渡す。書かなければ 0
	Offset *int64 `json:"offset,omitempty"`

	// 返す要素の数の上限。書かなければ 1000
	Limit *int64 `json:"limit,omitempty"`

	// 返すフィールドの名前。1 つ以上で、重ねない。id は書かなくても返す。書かなければ id・kind・layer・source を返す（決定 0118）
	Fields []EntityField `json:"fields,omitempty"`

	// [最小の X, 最小の Y, 最大の X, 最大の Y]。範囲がこの長方形と重なるか接する要素だけを返す。空間か用紙それぞれの座標で比べる（決定 0118）
	Region []float64 `json:"region,omitempty"`

	// 空間か用紙の ID（space/0・sheet/h22 など）。書けば、その空間か用紙の要素だけを返す。記号の定義の空間（space/h1F など。BLOCK のハンドルから作る、決定 0156）も指せ、書かなければ定義の中の要素は返さない。ない ID なら要素を返さない。マイナーバージョン 31 から（決定 0177）
	Place *string `json:"place,omitempty"`

	// 要素の公開 ID の一覧。いずれかに一致する要素だけを返す。空なら要素を返さず、ない ID は無視する。重複しても要素を増やさない。ほかの条件とも合わせる。マイナーバージョン 80 から
	Ids []string `json:"ids,omitempty"`

	// tables.layers の公開 ID の一覧。名前ではない。いずれかのレイヤの要素だけを返す。空なら要素を返さず、ない ID は無視する。ほかの条件とも合わせる。マイナーバージョン 80 から
	Layers []string `json:"layers,omitempty"`

	// 要素の種類の一覧。いずれかの種類だけを返す。空なら要素を返さず、重複しても要素を増やさない。ほかの条件とも合わせる。マイナーバージョン 80 から
	Kinds []EntityKind `json:"kinds,omitempty"`

	// 出所の条件。指定したすべての項目を満たす要素だけを返す。ほかの条件とも合わせる。マイナーバージョン 80 から
	Source *EntitySourceFilter `json:"source,omitempty"`
}

// MarshalJSON は、タグのフィールドを入れて書く。
func (m EntitiesRequest) MarshalJSON() ([]byte, error) {
	type plain EntitiesRequest
	m.Op = "entities"
	return json.Marshal(plain(m))
}

// EntitySourceFilter: 元の要素の出所による条件。空のオブジェクトなら制限しない。出所を持たない要素は指定した条件を満たさない
type EntitySourceFilter struct {
	// L1 のレコード番号と完全に一致する
	Record *int64 `json:"record,omitempty"`

	// L1 のバイト範囲との重なり。start を含み end を含まない、空でない範囲。境界が接するだけなら一致しない
	Bytes *ByteRange `json:"bytes,omitempty"`

	// AutoCAD のハンドル。接頭辞なし、1〜16 桁の 16 進の文字列。大文字と小文字を区別せず、数値で比べる。instance とは同時に指定できない
	Handle *string `json:"handle,omitempty"`

	// SXF のインスタンス番号。1〜20 桁の符号なし 64 bit 整数の 10 進文字列。数値で比べる。handle とは同時に指定できない
	Instance *string `json:"instance,omitempty"`
}

// EntitiesResult: 要素の一覧の一部。移さなかった図形と値は、診断で返す
type EntitiesResult struct {
	// offset から limit 個までの要素
	Items []Entity `json:"items,omitempty"`

	// 全体の要素の数
	Total *int64 `json:"total,omitempty"`

	// 続きの最初の要素の位置。続きがなければ持たない
	NextOffset *int64 `json:"next_offset,omitempty"`
}

// Entity: 図面モデルの要素
type Entity struct {
	// 空間か用紙と、出所で作る ID（space/0/h2F、space/0/r12、sheet/1/b4096 など）。出所の部分は、形式が持つキー（ハンドル）があればキーで作り、書き戻しても前の要素が増えても変わらない。同じバイト列には、どのバージョンでも同じ ID を返す（決定 0117・0156）
	Id *string `json:"id,omitempty"`

	// 形の種類
	Kind *EntityKind `json:"kind,omitempty"`

	// レイヤの元の名前。翻訳しない。図面モデルにレイヤがなければ持たない
	Layer *string `json:"layer,omitempty"`

	// 元の形式のレコード
	Source *Source `json:"source,omitempty"`

	// 形の定義から求めた範囲。文字の字形・線の太さ・記号の中身は含めない。囲む点がなければ持たない（決定 0118）
	Bbox *Extent `json:"bbox,omitempty"`

	// 要素のレイヤ・スタイル・形のハッシュ。出所の位置は含めない。変更の前提条件に使う（v2: と 32 桁の 16 進、決定 0156）
	Hash *string `json:"hash,omitempty"`

	// 形の値。線分・円・円弧・楕円・幅を持たない折れ線・1 点か 2 点の間に置く文字・書式つきの文字・ブロックの記号・制御点かフィット点で決まるスプライン・寸法・引出線（LEADER）・点・引出線つきの注記・表（ACAD_TABLE）だけが持つ。apply の replace と add に渡せる形（決定 0139）。マイナーバージョン 10 から
	Geometry Geometry `json:"geometry,omitempty"`

	// 要素自身のスタイル。fields に style を指定したときだけ返す。マイナーバージョン 79 から
	Style *EntityStyle `json:"style,omitempty"`

	// 要素に付く拡張の一覧。fields に extensions を指定したときだけ返し、拡張がなければ空の一覧。マイナーバージョン 79 から
	Extensions []EntityExtension `json:"extensions,omitempty"`
}

// EntityField: entities で返す要素のフィールド（決定 0118）
//
// 列挙の値。知らない値も受け取る。
type EntityField string

// EntityFieldId は id。
const EntityFieldId EntityField = "id"

// EntityFieldKind は kind。
const EntityFieldKind EntityField = "kind"

// EntityFieldLayer は layer。
const EntityFieldLayer EntityField = "layer"

// EntityFieldSource は source。
const EntityFieldSource EntityField = "source"

// EntityFieldBbox は bbox。
const EntityFieldBbox EntityField = "bbox"

// EntityFieldHash は hash。
const EntityFieldHash EntityField = "hash"

// EntityFieldGeometry は geometry。
const EntityFieldGeometry EntityField = "geometry"

// EntityFieldStyle は style。
const EntityFieldStyle EntityField = "style"

// EntityFieldExtensions は extensions。
const EntityFieldExtensions EntityField = "extensions"

// EntityStyle: 要素自身が持つスタイル。継承は解かず、色表の RGB も補わない。色・線種・線幅の形は restyle と同じ。透過性は読むだけで、restyle の指定には含めない
type EntityStyle struct {
	// 色の符号・図面内 RGB、または継承元
	Color *ColorChange `json:"color,omitempty"`

	// 継承元か、tables が返す線種の公開 ID
	LineType *LineTypeChange `json:"line_type,omitempty"`

	// 要素自身の線種の倍率。文書や配置の倍率を掛けない
	LineTypeScale *float64 `json:"line_type_scale,omitempty"`

	// 線幅の指定。元の形式から読めていなければ持たない
	LineWeight *LineWeightChange `json:"line_weight,omitempty"`

	// 透過性の指定
	Transparency *EntityTransparency `json:"transparency,omitempty"`
}

// EntityTransparency: 透過性。inherit または alpha の一方を返す
type EntityTransparency struct {
	// 継承元
	Inherit *Inherit `json:"inherit,omitempty"`

	// 不透明度。0 は透明、255 は不透明
	Alpha *int64 `json:"alpha,omitempty"`
}

// EntityExtension: 要素に付く形式固有の情報。元の順序を保ち、失効した値も current を偽にして返す。書き戻す操作ではない
type EntityExtension struct {
	// 値の型を定める名前空間
	Namespace *string `json:"namespace,omitempty"`

	// 元の名前。翻訳しない
	Name *string `json:"name,omitempty"`

	// 元の形式のバージョン。不明なら持たない
	Version *string `json:"version,omitempty"`

	// 名前空間の値の型のバージョン
	Schema *int64 `json:"schema,omitempty"`

	// 拡張が依存する元の要素のハッシュ。要素に依存するハッシュがなければ持たない
	Basis *string `json:"basis,omitempty"`

	// basis が現在の要素のハッシュと一致する
	Current *bool `json:"current,omitempty"`

	// 元の順序と型を保つフィールド
	Fields []EntityExtensionField `json:"fields,omitempty"`

	// 拡張の出所
	Source *Source `json:"source,omitempty"`
}

// EntityExtensionField: 拡張のフィールド。同じキーの重複と並びを保つ
