// SeverityWarning は warning。
const SeverityWarning Severity = "warning"

// SeverityError は error。
const SeverityError Severity = "error"

// Fidelity: 変換の結果の段のうち、`native` 以外のもの（決定 0009）
//
// 列挙の値。知らない値も受け取る。
