// FidelityEquivalent は equivalent。
const FidelityEquivalent Fidelity = "equivalent"

// FidelityApproximated は approximated。
const FidelityApproximated Fidelity = "approximated"

// FidelityDrawn は drawn。
const FidelityDrawn Fidelity = "drawn"

// FidelityDropped は dropped。
const FidelityDropped Fidelity = "dropped"

// Place: 診断の場所。ID と、L1 のレコード・バイト範囲（決定 0008 の出所）
