// BlobKindImage は image。
const BlobKindImage BlobKind = "image"

// BlobKindScene は scene。
const BlobKindScene BlobKind = "scene"

// BlobKindArrow は arrow。
const BlobKindArrow BlobKind = "arrow"

// BlobKindDrawing は drawing。
const BlobKindDrawing BlobKind = "drawing"

// BlobKindScene3d は scene3d。
const BlobKindScene3d BlobKind = "scene3d"

// SessionOptions: zm_session_new に渡す設定。渡さなければ既定の設定
type SessionOptions struct {
	// メッセージのスキーマのメジャーバージョン。今は 1
	V *int64 `json:"v,omitempty"`

	// 実行の形態。書かなければ、ネイティブのライブラリでは `native`、wasm のモジュールでは `wasm`（決定 0013）
	Engine *Engine `json:"engine,omitempty"`

	// engine が `process` のときの、子プロセスにする CLI（zumen）の実行ファイルのパス。書かなければ、ライブラリと同じフォルダーの zumen を使う（決定 0013・0200）
	ProcessPath *string `json:"process_path,omitempty"`
}

// Engine: 実行の形態（決定 0013）。`native` はプロセスの中でコアを動かす、`process` は子プロセスの CLI に送る、`wasm` は wasm のモジュールで動かす
//
// 列挙の値。知らない値も受け取る。
type Engine string

// EngineNative は native。
