const GeoValueKindMeasure GeoValueKind = "measure"

// GeoForm: 形の種類
//
// 列挙の値。知らない値も受け取る。
type GeoForm string

// GeoFormPoint は point。
const GeoFormPoint GeoForm = "point"

// GeoFormLine は line。
const GeoFormLine GeoForm = "line"

// GeoFormArea は area。
const GeoFormArea GeoForm = "area"

// GeoFormSolid は solid。
const GeoFormSolid GeoForm = "solid"

// GeoGeometry: 形の要約
type GeoGeometry struct {
	// LOD。2D の地物は書かない
	Lod *int64 `json:"lod,omitempty"`

	// 形の種類
	Form *GeoForm `json:"form,omitempty"`

	// 点の数。立体と面の集まりは、面の輪の点の数の和
	Points *int64 `json:"points,omitempty"`

	// 立体と面の集まりの面の数
	Faces *int64 `json:"faces,omitempty"`
}

// CivilDrawingRequest: open で開いた J-LandXML・IFC4.3・SIMA の文書の線形から、平面図・縦断図・横断図の図面モデルを作り（決定 0231）、用紙を 1 枚選んで新しい DXF の文書として開く（決定 0239）。尺度・文字の高さ・測点の間隔は、プロファイルを渡せば語彙 civil-drawing と text-height から読み、渡さなければ作図の慣習の値にする。縦断図は用紙の要素に焼き込む（決定 0238）。書いたファイルは blobs で返す。作った文書は scene と check に渡せる。図面のモジュールに置く。マイナーバージョン 51 から
type CivilDrawingRequest struct {
	// メッセージのスキーマのメジャーバージョン。今は 1
	V *int64 `json:"v,omitempty"`

	// 予算の単位ごとの上限。書かない単位は既定値にする（決定 0010）
	Budget *Budget `json:"budget,omitempty"`

	// 予算で止まったとき、止まった所までの結果を求める。書かなければ false（決定 0010）
	Partial *bool `json:"partial,omitempty"`

	// 診断ごとに返す場所の数。書かなければ 16（決定 0009）
	MaxPlaces *int64 `json:"max_places,omitempty"`

	// 時間の上限（ミリ秒）。ネイティブの API が時計を見て止める。止まる所は環境で変わる。wasm では受け付けない（決定 0010）
	TimeLimitMs *int64 `json:"time_limit_ms,omitempty"`

	// op の名前
	Op string `json:"op,omitempty"`

	// open で開いた J-LandXML・IFC4.3・SIMA の文書の名前
	Doc *string `json:"doc,omitempty"`

	// doc の線形の ID。文書に線形が 1 つなら書かなくてよい
	Id *string `json:"id,omitempty"`

	// 書く用紙の名前（結果の sheets の 1 つ）。書かなければ平面図
	Sheet *string `json:"sheet,omitempty"`

	// 作る文書の名前
	To *string `json:"to,omitempty"`

	// プロファイルの入力の名前の列（zm_push で渡した profile.json）。extends で指す先も、すべて渡す
	Profiles []string `json:"profiles,omitempty"`

	// 作図の値に使うプロファイル。profiles の中から選ぶ。profiles と一緒に書く
	Profile *ProfileRef `json:"profile,omitempty"`
}

// MarshalJSON は、タグのフィールドを入れて書く。
func (m CivilDrawingRequest) MarshalJSON() ([]byte, error) {
	type plain CivilDrawingRequest
	m.Op = "civil_drawing"
	return json.Marshal(plain(m))
}

// CivilDrawingResult: 作った文書。書いたファイルは blobs の file で返す
type CivilDrawingResult struct {
	// 作った文書の名前
	Doc *string `json:"doc,omitempty"`

	// 書いた形式の名前。今は dxf
	Format *string `json:"format,omitempty"`

	// 書いたファイルのハッシュ。apply の前提条件に使う
	Hash *string `json:"hash,omitempty"`

	// 書いた要素の数
	Elements *int64 `json:"elements,omitempty"`

	// 図を作った線形の ID
	Alignment *string `json:"alignment,omitempty"`

	// 作った用紙の名前。図を描ける順（平面図・縦断図・横断図）
	Sheets []string `json:"sheets,omitempty"`

	// 書いた用紙の名前
	Sheet *string `json:"sheet,omitempty"`

	// 使った作図の値
	Options *CivilDrawingOptions `json:"options,omitempty"`

	// 作図の値を読んだプロファイルの、extends を解いた鎖。基から順。プロファイルを渡さなければ書かない
	Profile []ProfileIdentity `json:"profile,omitempty"`
}

// CivilDrawingOptions: 土木の図の作図の値
type CivilDrawingOptions struct {
	// 平面図の尺度の分母
	Plan *float64 `json:"plan,omitempty"`

	// 縦断図の横の尺度の分母
	Horizontal *float64 `json:"horizontal,omitempty"`

	// 縦断図の縦の尺度の分母
	Vertical *float64 `json:"vertical,omitempty"`

	// 横断図の尺度の分母
	CrossSection *float64 `json:"cross_section,omitempty"`

	// 文字の高さ（mm）
	TextHeight *float64 `json:"text_height,omitempty"`

	// 測点の間隔（メートル）
	StationPitch *float64 `json:"station_pitch,omitempty"`
}

// DeviationRequest: 開いた点群と、土木の文書の TIN の標高の差を求め、プロファイルの surface-elevation の規則の区分ごとに集計して、規格値と比べる（決定 0234）。点群のモジュールに置く（決定 0253）。マイナーバージョン 50 から
type DeviationRequest struct {
	// メッセージのスキーマのメジャーバージョン。今は 1
	V *int64 `json:"v,omitempty"`

	// 予算の単位ごとの上限。書かない単位は既定値にする（決定 0010）
	Budget *Budget `json:"budget,omitempty"`

	// 予算で止まったとき、止まった所までの結果を求める。書かなければ false（決定 0010）
	Partial *bool `json:"partial,omitempty"`

	// 診断ごとに返す場所の数。書かなければ 16（決定 0009）
	MaxPlaces *int64 `json:"max_places,omitempty"`

	// 時間の上限（ミリ秒）。ネイティブの API が時計を見て止める。止まる所は環境で変わる。wasm では受け付けない（決定 0010）
	TimeLimitMs *int64 `json:"time_limit_ms,omitempty"`

	// op の名前
	Op string `json:"op,omitempty"`

	// open で開いた点群の文書の名前
	Doc *string `json:"doc,omitempty"`

	// 設計面の TIN
	Surface *DeviationSurface `json:"surface,omitempty"`

	// プロファイルの入力の名前の列（zm_push で渡した profile.json）。extends で指す先も、すべて渡す
	Profiles []string `json:"profiles,omitempty"`

	// 規格値に使うプロファイル。profiles の中から選ぶ
	Profile *ProfileRef `json:"profile,omitempty"`

	// 工種の名前。規則の work と比べ、同じものだけを使う
	Work *string `json:"work,omitempty"`

	// 返す最初の評価した点の位置。前の応答の next_offset を渡す。書かなければ 0
	Offset *int64 `json:"offset,omitempty"`

	// 返す評価した点の数の上限。書かなければ点を返さない
	Limit *int64 `json:"limit,omitempty"`

	// 差の色の段で点を塗った 3D のシーンも返す。点の選び方は点群の scene3d と同じ。89 から
	Scene3d *DeviationScene3d `json:"scene3d,omitempty"`
}

// MarshalJSON は、タグのフィールドを入れて書く。
func (m DeviationRequest) MarshalJSON() ([]byte, error) {
	type plain DeviationRequest
	m.Op = "deviation"
	return json.Marshal(plain(m))
}

// DeviationSurface: 設計面の TIN を持つ文書と、TIN の ID
type DeviationSurface struct {
	// open で開いた土木の文書の名前
	Doc *string `json:"doc,omitempty"`

	// TIN の ID。civil の surfaces の id
	Id *string `json:"id,omitempty"`
}

// DeviationResult: 標高の差の、規則の区分ごとの集計と指摘。合格・適合とは言わない
type DeviationResult struct {
	// 使ったプロファイルの鎖。extends の基から順
	Chain []ProfileIdentity `json:"chain,omitempty"`

	// 点群の点の数
	Points *int64 `json:"points,omitempty"`

	// TIN の外なので評価しなかった点の数
	Outside *int64 `json:"outside,omitempty"`

	// どの規則の勾配にも入らない三角形の上なので評価しなかった点の数
	Unmatched *int64 `json:"unmatched,omitempty"`

	// 区分の境の近く（規則の exclude の内）なので除いた点の数
	Excluded *int64 `json:"excluded,omitempty"`

	// 規則ごとの集計。プロファイルの順。使えない規則は持たず、profile.rule.unsupported の診断で返す
	Rules []DeviationRule `json:"rules,omitempty"`

	// 指摘。規則の順。規格値を外れれば profile.surface-elevation.invalid、確認できなければ profile.surface-elevation.unsupported
	Findings []CheckFinding `json:"findings,omitempty"`

	// 評価した点の数
	Evaluated *int64 `json:"evaluated,omitempty"`

	// 評価した点。点群の順に、offset から limit 個まで
	Differences []DeviationPoint `json:"differences,omitempty"`

	// 続きの最初の評価した点の位置。続きがなければ持たない
	NextOffset *int64 `json:"next_offset,omitempty"`

	// 要求に scene3d を書いたときの 3D のシーン。点の色は bands の段の色で、元の色は持たない。強度と分類は元の値。89 から
	Scene3d *Scene3dResult `json:"scene3d,omitempty"`

	// 要求に scene3d を書いたときの色の段。規則の順に、その規則で起こりうる段を、差の小さい順に並べ、最後に評価しなかった点の段を置く。89 から
	Bands []DeviationBand `json:"bands,omitempty"`
}

// DeviationScene3d: 差の色分けの 3D のシーンの点の選び方。意味は点群の scene3d の box・tolerance・limit と同じ
type DeviationScene3d struct {
	// 点群の元の座標系の東・北・高さのメートルの箱
	Box *Scene3dBox `json:"box,omitempty"`

	// 点の間隔（メートル）の正の有限値。これより細かい段の節を選ばない
	Tolerance *float64 `json:"tolerance,omitempty"`

	// 返す点の数の上限。省略時は選んだすべての点
	Limit *int64 `json:"limit,omitempty"`
}

// DeviationBand: 差の色の段。差は mm で、規則の each（個々の計測値の規格値）から決める。下限より小さい差は below、上限より大きい差は above で、規格値ちょうどは内側に入れる。内側は 0 から規格値の半分までと、半分から規格値までに分け、境の値は 0 に近い段に入れる。0 は high_inner。規格値のない側は inner の 1 段だけにする
type DeviationBand struct {
	// 規則の id。評価しなかった点の段は持たない
	Rule *string `json:"rule,omitempty"`

	// 段の名前
	Band *DeviationBandKind `json:"band,omitempty"`

	// 段の下の端の差（mm）。下に端がなければ持たない
	Lower *float64 `json:"lower,omitempty"`

	// 段の上の端の差（mm）。上に端がなければ持たない
	Upper *float64 `json:"upper,omitempty"`

	// シーンの点の色。16 ビットの赤・緑・青・不透明度
	Color []int64 `json:"color,omitempty"`
}

// DeviationBandKind: 差の色の段。not_evaluated は TIN の外・どの規則の勾配にも入らない・区分の境の近くで除いた点
//
// 列挙の値。知らない値も受け取る。
type DeviationBandKind string

// DeviationBandKindBelow は below。
const DeviationBandKindBelow DeviationBandKind = "below"

// DeviationBandKindLowOuter は low_outer。
const DeviationBandKindLowOuter DeviationBandKind = "low_outer"

// DeviationBandKindLowInner は low_inner。
const DeviationBandKindLowInner DeviationBandKind = "low_inner"

// DeviationBandKindHighInner は high_inner。
const DeviationBandKindHighInner DeviationBandKind = "high_inner"

// DeviationBandKindHighOuter は high_outer。
const DeviationBandKindHighOuter DeviationBandKind = "high_outer"

// DeviationBandKindAbove は above。
const DeviationBandKindAbove DeviationBandKind = "above"

// DeviationBandKindNotEvaluated は not_evaluated。
const DeviationBandKindNotEvaluated DeviationBandKind = "not_evaluated"

// DeviationRule: 規則の区分ごとの集計。差はメートル
type DeviationRule struct {
	// 規則の id
	Rule *string `json:"rule,omitempty"`

	// 区分の名前
	Part *string `json:"part,omitempty"`

	// 評価した点の数
	Points *int64 `json:"points,omitempty"`

	// 区分の三角形の、平面に投影した面積（m²）
	Area *float64 `json:"area,omitempty"`

	// 計測の密度（点／m²）。面積がなければ書かない
	Density *float64 `json:"density,omitempty"`

	// 差の平均。点がなければ書かない
	Mean *float64 `json:"mean,omitempty"`

	// 差の最小。点がなければ書かない
	Min *float64 `json:"min,omitempty"`

	// 差の最大。点がなければ書かない
	Max *float64 `json:"max,omitempty"`

	// 指摘の数（確認できなかったものを除く）
	Findings *int64 `json:"findings,omitempty"`

	// 確認できなかった数
	Unsupported *int64 `json:"unsupported,omitempty"`
}

// DeviationPoint: 評価した点
type DeviationPoint struct {
	// 点群の中の番号
	Index *int64 `json:"index,omitempty"`

	// 北・東・標高（メートル）
	Position []float64 `json:"position,omitempty"`

	// 点の標高から設計面の標高を引いた差（メートル）
	Difference *float64 `json:"difference,omitempty"`

	// 評価した規則の id
	Rule *string `json:"rule,omitempty"`
}

// Catalog: describe に使うカタログのファイル。catalog/<言語>.toml から生成し、zm_push で渡す（決定 0009）
type Catalog struct {
	// カタログの形のメジャーバージョン。今は 1
	V *int64 `json:"v,omitempty"`

	// 言語（ja・en）
	Lang *string `json:"lang,omitempty"`

	// パッケージのバージョン。コアと同じバージョンで出す
	Package *string `json:"package,omitempty"`

	// 数の書き方
	Number *NumberFormat `json:"number,omitempty"`

	// code ごとの文のひな形。{名前} に値が、{count} にまとめた件数が入る
	Codes map[string]string `json:"codes,omitempty"`
}

// NumberFormat: 文に差し込む数の書き方。OS のロケールは使わない（決定 0009）
type NumberFormat struct {
	// 整数部を 3 桁ごとに区切る文字。空なら区切らない
	GroupSeparator *string `json:"group_separator,omitempty"`

	// 小数点の文字
	DecimalSeparator *string `json:"decimal_separator,omitempty"`
}

